import { RIVET_VERSION } from '../../config/telemetry';
import { updateHarnesses } from '../../install/harnesses';
import { errorResult, okResult, type CliCommandResult } from '../envelope';
import { isNewerVersion } from '../serverVersion';
import { isCommandResult, parseCommandContext } from './shared';
import { synchronizeRuntimes } from '../synchronizeRuntimes';
import { processCliIO } from '../io';

const COMMAND = 'update';
const UPDATE_CHECKED_VERSION_ENV = 'RIVET_UPDATE_CHECKED_VERSION';
const UPDATE_FAILURE_ENV = 'RIVET_UPDATE_FAILURE';
const UPDATE_PACKAGE_UPDATED_ENV = 'RIVET_UPDATE_PACKAGE_UPDATED';

type UpdateFailure = {
  currentVersion: string;
  phase: string;
  reason: string;
  targetVersion?: string;
};

const takeUpdateFailure = (): UpdateFailure | null => {
  const serializedFailure = process.env[UPDATE_FAILURE_ENV];
  delete process.env[UPDATE_FAILURE_ENV];
  if (!serializedFailure) return null;
  try {
    const failure = JSON.parse(serializedFailure) as Partial<UpdateFailure>;
    if (
      typeof failure.currentVersion !== 'string' ||
      typeof failure.phase !== 'string' ||
      typeof failure.reason !== 'string' ||
      (failure.targetVersion !== undefined &&
        typeof failure.targetVersion !== 'string')
    ) {
      return null;
    }
    return failure as UpdateFailure;
  } catch {
    return null;
  }
};

export const handleUpdate = async (
  args: string[],
): Promise<CliCommandResult> => {
  const context = parseCommandContext(COMMAND, args);
  if (isCommandResult(context)) return context;
  if (context.flags.positionals.length > 0) {
    return errorResult(COMMAND, 'USAGE_ERROR', 'Usage: rivet update');
  }

  const updateFailure = takeUpdateFailure();
  const checkedVersion =
    process.env[UPDATE_CHECKED_VERSION_ENV] ??
    updateFailure?.targetVersion ??
    RIVET_VERSION;
  const wasPackageUpdated = process.env[UPDATE_PACKAGE_UPDATED_ENV] === '1';
  delete process.env[UPDATE_CHECKED_VERSION_ENV];
  delete process.env[UPDATE_PACKAGE_UPDATED_ENV];
  const integrations = updateHarnesses({ isQuiet: true });
  const runtimes = await synchronizeRuntimes({ args, io: processCliIO });
  const result = {
    currentVersion: RIVET_VERSION,
    checkedVersion,
    isLatest: !isNewerVersion(checkedVersion, RIVET_VERSION),
    wasPackageUpdated,
    integrations,
    runtimes,
  };

  if (updateFailure) {
    const message = updateFailure.targetVersion
      ? `Rivet could not update to v${updateFailure.targetVersion}; continuing with v${updateFailure.currentVersion}.`
      : `Rivet could not check for updates; continuing with v${updateFailure.currentVersion}.`;
    return errorResult(COMMAND, 'OPERATION_FAILED', message, {
      ...result,
      updateFailure,
    });
  }
  if (runtimes.failures.length > 0) {
    return errorResult(
      COMMAND,
      'SERVER_UNAVAILABLE',
      'The CLI was updated, but some running servers could not be upgraded.',
      result,
      { isRecoverable: true },
    );
  }
  if (!integrations.isSuccessful) {
    return errorResult(
      COMMAND,
      'OPERATION_FAILED',
      'The CLI is current, but some agent integrations could not be refreshed.',
      result,
    );
  }
  return okResult(COMMAND, result);
};
